package com.sakti.banking.service; import com.sakti.banking.dto.ServiceRequestRequest; import com.sakti.banking.entity.*; import com.sakti.banking.repository.ServiceRequestRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class ServiceRequestService {private final ServiceRequestRepository repo;private final UserService users;public ServiceRequestService(ServiceRequestRepository r,UserService u){repo=r;users=u;} public ServiceRequest create(String email,ServiceRequestRequest r){ServiceRequest s=new ServiceRequest();s.setOwner(users.requireByEmail(email));s.setType(r.type());s.setDetails(r.details());return repo.save(s);}public List<ServiceRequest> mine(String email){return repo.findByOwnerEmailIgnoreCaseOrderByCreatedAtDesc(email);} }
